# Crea los íconos del escáner en public\img (desde la raíz del proyecto)
New-Item -ItemType Directory -Force "public\img" | Out-Null
[IO.File]::WriteAllBytes("$PWD\public\img\escaner-192.png", [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes("$PWD\public\img\escaner-512.png", [Convert]::FromBase64String(""))
Get-ChildItem "public\img\escaner-*.png" | Format-Table Name, Length
